1	package chainledger
2	
3	import (
4		"encoding/json"
5		"io"
6		"sort"
7		"strings"
8		"unicode/utf8"
9	)
10	
11	// ImportLineage decodes a lineage document in the same JSON shape the exports
12	// produce and returns a brand-new, independent lineage graph holding exactly
13	// the document's nodes and direct dependencies. The returned map works with
14	// every existing operation: Register, Rename, Unregister, Impacts,
15	// ImpactsWithCutoffs, Upstreams, CommonUpstreams, Roots and both exports. The
16	// caller's own graph is never read or modified — import only creates a new map.
17	//
18	// The document is one single JSON object with two array fields:
19	//
20	//   - "nodes": dataset names. Every listed node exists in the new graph,
21	//     including independent datasets with no dependency in either direction.
22	//     A name listed more than once counts once.
23	//   - "edges": direct dependencies written {"from": upstream, "to": derived},
24	//     the same direction the exports use. Each edge becomes the derived
25	//     dataset's direct upstream (Parents) and, mirrored, the upstream's direct
26	//     downstream (Children). The same dependency listed more than once counts
27	//     once.
28	//
29	// Import scope is exactly the document: nothing is invented, inferred or
30	// completed. A document produced by a source-scoped export rebuilds only that
31	// part of the lineage — other sources and downstreams the export omitted are
32	// not restored. Direct relations and longer branches through intermediate
33	// nodes are kept together, so explanation paths are still chosen by the
34	// existing query rules (fewest edges, then the lexicographically smallest full
35	// path in Go string order).
36	//
37	// Nodes and edges may appear in the document in any order; the result is
38	// independent of that order. Every node's direct upstream and downstream
39	// lists are stored in Go string order, so a graph imported from a valid export
40	// document re-exports byte-identical text for the same target or source-target
41	// pair.
42	//
43	// Names are identified by their exact decoded JSON value: matching is
44	// case-sensitive and spaces, Chinese characters, quotes, backslashes and
45	// newlines are preserved verbatim — never trimmed or rewritten. The input
46	// must be valid UTF-8 and hold exactly one complete JSON object; "nodes" and
47	// "edges" must both be present, each as an array of the correct element type
48	// (null is not an array). Two empty arrays import successfully as an empty,
49	// ready-to-register graph.
50	//
51	// The whole document is validated before the graph is returned, so every
52	// failure yields a nil graph and an error describing the document problem,
53	// never a partial graph:
54	//
55	//   - Empty or whitespace-only text, text that is not valid UTF-8, malformed
56	//     JSON, more than one JSON value, a non-object document, a duplicated
57	//     object key, a missing or null array, or an element of the wrong type is
58	//     rejected.
59	//   - An empty node name is rejected as a missing name.
60	//   - Both endpoints of every edge must be listed in nodes; an edge naming a
61	//     dataset the document does not list fails the whole import, and the error
62	//     names that dataset. Edges missing an endpoint are rejected the same way.
63	//   - A self-dependency or a dependency cycle of any length fails the whole
64	//     import; the error states that the lineage contains a cycle and names the
65	//     datasets on it.
66	func ImportLineage(text string) (map[string]*Lineage, error) {
67		nodesRaw, edgesRaw, err := decodeLineageDocument(text)
68		if err != nil {
69			return nil, err
70		}
71	
72		var nodeItems []json.RawMessage
73		if err := json.Unmarshal(nodesRaw, &nodeItems); err != nil {
74			return nil, errInvalid("lineage document nodes must be an array of JSON strings: " + err.Error())
75		}
76		var edgeItems []json.RawMessage
77		if err := json.Unmarshal(edgesRaw, &edgeItems); err != nil {
78			return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
79		}
80	
81		// Build the de-duplicated node set. Each element must itself be a JSON
82		// string (null is not a name). Names keep their exact decoded value: the
83		// document was already checked to be valid UTF-8, so every decoded name is
84		// the original value, with JSON unescaping applied (quotes, backslashes,
85		// newlines and all).
86		nodes := make(map[string]bool, len(nodeItems))
87		for _, item := range nodeItems {
88			trimmed := strings.TrimSpace(string(item))
89			if !strings.HasPrefix(trimmed, `"`) {
90				return nil, errInvalid("lineage document nodes must be an array of JSON strings")
91			}
92			var name string
93			if err := json.Unmarshal(item, &name); err != nil {
94				return nil, errInvalid("lineage document nodes must be an array of JSON strings: " + err.Error())
95			}
96			if name == "" {
97				return nil, errInvalid("dataset name is required")
98			}
99			nodes[name] = true
100		}
101	
102		// Resolve every edge before constructing entries. Each element must be a
103		// {"from": ..., "to": ...} object; both endpoints must be listed nodes.
104		// De-duplicated dependencies only, independent of document order.
105		dependencies := make(map[lineageExportEdge]bool, len(edgeItems))
106		for _, item := range edgeItems {
107			trimmed := strings.TrimSpace(string(item))
108			if !strings.HasPrefix(trimmed, "{") {
109				return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects`)
110			}
111			var edge lineageExportEdge
112			if err := json.Unmarshal(item, &edge); err != nil {
113				return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
114			}
115			if edge.From == "" {
116				return nil, errInvalid(`lineage document edge is missing its upstream endpoint ("from")`)
117			}
118			if edge.To == "" {
119				return nil, errInvalid(`lineage document edge is missing its derived endpoint ("to")`)
120			}
121			if !nodes[edge.From] {
122				return nil, errInvalid("edge endpoint not listed in nodes: " + edge.From)
123			}
124			if !nodes[edge.To] {
125				return nil, errInvalid("edge endpoint not listed in nodes: " + edge.To)
126			}
127			dependencies[edge] = true
128		}
129	
130		// Materialize the new graph with direct lists in Go string order. All
131		// entries exist before any edge is attached, and a rejected import returns
132		// nil, so a caller can never observe a partially filled graph.
133		graph := make(map[string]*Lineage, len(nodes))
134		for name := range nodes {
135			graph[name] = &Lineage{Dataset: name}
136		}
137		for edge := range dependencies {
138			graph[edge.To].Parents = append(graph[edge.To].Parents, edge.From)
139			graph[edge.From].Children = append(graph[edge.From].Children, edge.To)
140		}
141		for _, entry := range graph {
142			sort.Strings(entry.Parents)
143			sort.Strings(entry.Children)
144		}
145	
146		// Cycles of any length (self dependencies included) are rejected with the
147		// datasets on one such cycle named deterministically.
148		if cycle := findLineageCycle(graph); cycle != nil {
149			return nil, errInvalid("lineage contains a cycle: " + strings.Join(cycle, " -> "))
150		}
151		return graph, nil
152	}
153	
154	// decodeLineageDocument runs the document-level checks and returns the raw
155	// JSON values of the nodes and edges arrays: the text must be non-empty, valid
156	// UTF-8, exactly one complete JSON object with no duplicated object key, and
157	// both fields must be present as arrays (null rejected, element types are
158	// checked by the caller's typed unmarshal).
159	func decodeLineageDocument(text string) (json.RawMessage, json.RawMessage, error) {
160		if strings.TrimSpace(text) == "" {
161			return nil, nil, errInvalid("lineage document is empty: expected one JSON object with nodes and edges arrays")
162		}
163		// encoding/json silently rewrites invalid UTF-8 into U+FFFD instead of
164		// failing, and two byte-different names could then collapse into one, so
165		// the whole text is checked before anything is decoded.
166		if !utf8.ValidString(text) {
167			return nil, nil, errInvalid("lineage document is not valid UTF-8")
168		}
169		if err := rejectDuplicateKeys(text); err != nil {
170			return nil, nil, err
171		}
172	
173		var raw map[string]json.RawMessage
174		if err := json.Unmarshal([]byte(text), &raw); err != nil {
175			return nil, nil, errInvalid("lineage document must be one complete JSON object: " + err.Error())
176		}
177	
178		nodes, ok := raw["nodes"]
179		if !ok {
180			return nil, nil, errInvalid(`lineage document is missing the "nodes" array`)
181		}
182		edges, ok := raw["edges"]
183		if !ok {
184			return nil, nil, errInvalid(`lineage document is missing the "edges" array`)
185		}
186		if err := requireJSONArray(nodes, "nodes"); err != nil {
187			return nil, nil, err
188		}
189		if err := requireJSONArray(edges, "edges"); err != nil {
190			return nil, nil, err
191		}
192		return nodes, edges, nil
193	}
194	
195	// requireJSONArray rejects a field that is null or whose value is not a JSON
196	// array; element types inside the array are validated by typed unmarshalling.
197	func requireJSONArray(raw json.RawMessage, field string) error {
198		trimmed := strings.TrimSpace(string(raw))
199		switch {
200		case trimmed == "null":
201			return errInvalid("lineage document field " + field + " must be an array, got null")
202		case !strings.HasPrefix(trimmed, "["):
203			return errInvalid("lineage document field " + field + " must be an array")
204		}
205		return nil
206	}
207	
208	// objectFrame tracks one container during the structural key scan: whether it
209	// is an object (arrays need no key tracking), whether the next string token is
210	// that object's key, and the keys already seen in it.
211	type objectFrame struct {
212		object    bool
213		expectKey bool
214		keys      map[string]bool
215	}
216	
217	// rejectDuplicateKeys tokenizes the text and rejects any JSON object that
218	// repeats a key, any document whose top-level value is not an object, and any
219	// trailing JSON value after the closing object. encoding/json accepts all
220	// three silently (last key wins; null decodes into a map as no value at all;
221	// trailing values are rejected by Unmarshal but with a generic message), so
222	// the explicit scan makes document problems deterministic.
223	func rejectDuplicateKeys(text string) error {
224		dec := json.NewDecoder(strings.NewReader(text))
225		var stack []objectFrame
226		rootClosed := false
227		for {
228			tok, err := dec.Token()
229			if err == io.EOF {
230				if len(stack) != 0 || !rootClosed {
231					return errInvalid("lineage document must be one complete JSON object")
232				}
233				return nil
234			}
235			// Anything at all after the root object closes is a second value or
236			// garbage, whether tokenized as a token or as a scan error.
237			if rootClosed {
238				return errInvalid("lineage document must hold exactly one JSON object")
239			}
240			if err != nil {
241				return errInvalid("lineage document must be one complete JSON object: " + err.Error())
242			}
243	
244			switch t := tok.(type) {
245			case json.Delim:
246				switch t {
247				case '{':
248					stack = append(stack, objectFrame{object: true, expectKey: true, keys: map[string]bool{}})
249				case '[':
250					if len(stack) == 0 {
251						return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got an array")
252					}
253					stack = append(stack, objectFrame{})
254				case '}', ']':
255					if len(stack) == 0 {
256						return errInvalid("lineage document has an unmatched " + string(t))
257					}
258					stack = stack[:len(stack)-1]
259					if len(stack) == 0 {
260						if t != '}' {
261							return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
262						}
263						rootClosed = true
264					} else if stack[len(stack)-1].object {
265						// A nested container was this object member's value; the
266						// next member, if any, starts with a key.
267						stack[len(stack)-1].expectKey = true
268					}
269				}
270			case string:
271				if len(stack) == 0 {
272					return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got a string")
273				}
274				top := &stack[len(stack)-1]
275				if !top.object {
276					continue // string element of an array; members are delimiter-tracked
277				}
278				if !top.expectKey {
279					top.expectKey = true // string value consumed; a key may follow
280					continue
281				}
282				if top.keys[t] {
283					return errInvalid("lineage document contains a duplicated object key: " + t)
284				}
285				top.keys[t] = true
286				top.expectKey = false
287			default: // number, bool, nil
288				if len(stack) == 0 {
289					return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
290				}
291				if stack[len(stack)-1].object {
292					stack[len(stack)-1].expectKey = true
293				}
294			}
295		}
296	}
297	
298	// findLineageCycle returns the datasets on one directed cycle written in the
299	// actual derivation direction (upstream -> derived), with the smallest-named
300	// dataset on the cycle first and repeated last, or nil when the graph is
301	// acyclic. Every node on a cycle reaches itself by following parent edges, so
302	// a depth-first walk with a per-path stack catches a back edge of any length,
303	// including a self dependency. Nodes are visited in Go string order and parent
304	// lists are already sorted, so the reported cycle is independent of the
305	// document's node and edge ordering.
306	func findLineageCycle(graph map[string]*Lineage) []string {
307		color := make(map[string]int, len(graph)) // 0 unseen, 1 on current path, 2 done
308		var stack []string
309		var found []string
310	
311		var visit func(node string) bool
312		visit = func(node string) bool {
313			color[node] = 1
314			stack = append(stack, node)
315			for _, parent := range graph[node].Parents {
316				switch color[parent] {
317				case 0:
318					if visit(parent) {
319						return true
320					}
321				case 1:
322					// A back edge to a node on the current path closes a cycle:
323					// parent ... node, with node deriving from parent.
324					start := 0
325					for stack[start] != parent {
326						start++
327					}
328					found = append([]string(nil), stack[start:]...)
329					return true
330				}
331			}
332			stack = stack[:len(stack)-1]
333			color[node] = 2
334			return false
335		}
336	
337		names := make([]string, 0, len(graph))
338		for name := range graph {
339			names = append(names, name)
340		}
341		sort.Strings(names)
342		for _, name := range names {
343			if color[name] == 0 && visit(name) {
344				return derivationCycle(found)
345			}
346		}
347		return nil
348	}
349	
350	// derivationCycle converts a closed cycle segment discovered while following
351	// parent edges into the derivation direction, then rotates it so the
352	// smallest-named dataset comes first (and stays last). A parent-direction
353	// segment [p0, p1, ..., pk] closes with pk deriving from p0, so the derivation
354	// runs p0 -> pk -> ... -> p1 -> p0.
355	func derivationCycle(parentPath []string) []string {
356		body := make([]string, 0, len(parentPath)+1)
357		body = append(body, parentPath[0])
358		for i := len(parentPath) - 1; i >= 1; i-- {
359			body = append(body, parentPath[i])
360		}
361	
362		min := 0
363		for i := 1; i < len(body); i++ {
364			if body[i] < body[min] {
365				min = i
366			}
367		}
368		rotated := make([]string, 0, len(body)+1)
369		rotated = append(rotated, body[min:]...)
370		rotated = append(rotated, body[:min]...)
371		rotated = append(rotated, body[min])
372		return rotated
373	}
