```go
// unpairedSurrogateEscape scans a valid JSON string literal (quotes included)
// for a \uXXXX escape in the UTF-16 surrogate range that does not form a valid
// pair: a high surrogate not immediately followed by a low-surrogate escape, or
// a low surrogate appearing on its own. It returns the offending escape exactly
// as written, or "" when every surrogate escape is properly paired. encoding/json
// decodes a lone surrogate to U+FFFD instead of failing, which would silently
// merge distinct names, so the raw literal is checked before the decoded value
// is trusted. An escaped backslash (\\) is consumed as a unit, so the text after
// it is never mistaken for an escape introducer.
func unpairedSurrogateEscape(literal string) string {
	s := literal[1 : len(literal)-1] // quotes guaranteed by the caller
	for i := 0; i < len(s); {
		if s[i] != '\\' {
			i++
			continue
		}
		if s[i+1] != 'u' {
			i += 2 // \\, \", \n, ... — the next byte is part of this escape
			continue
		}
		escape := s[i : i+6]
		cp, _ := strconv.ParseUint(s[i+2:i+6], 16, 32)
		switch {
		case cp >= 0xD800 && cp <= 0xDBFF:
			// A high surrogate is valid only as half of a pair: the very next
			// thing in the string must be a low-surrogate escape.
			if i+12 <= len(s) && s[i+6] == '\\' && s[i+7] == 'u' {
				if lo, _ := strconv.ParseUint(s[i+8:i+12], 16, 32); lo >= 0xDC00 && lo <= 0xDFFF {
					i += 12
					continue
				}
			}
			return escape
		case cp >= 0xDC00 && cp <= 0xDFFF:
			return escape // a low surrogate without a preceding high surrogate
		}
		i += 6
	}
	return ""
}
```

